import heapq

def topo_order(nodes, edges):
    all_nodes = set(nodes)
    for a, b in edges:
        all_nodes.add(a)
        all_nodes.add(b)

    indegree = {n: 0 for n in all_nodes}
    adj = {n: [] for n in all_nodes}
    for a, b in edges:
        adj[a].append(b)
        indegree[b] += 1

    heap = [n for n in all_nodes if indegree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        n = heapq.heappop(heap)
        result.append(n)
        for m in adj[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(heap, m)

    if len(result) != len(all_nodes):
        raise ValueError("Graph has a cycle")

    return result
